import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.D7WGirly.js";const k=JSON.parse('{"title":"Working with coding agents","description":"How a coding agent builds terminal UIs with Tuimark - the AGENTS.md briefing from tuimark agents, the validate, dump and play loop, and the rules that keep it on track.","frontmatter":{"title":"Working with coding agents","description":"How a coding agent builds terminal UIs with Tuimark - the AGENTS.md briefing from tuimark agents, the validate, dump and play loop, and the rules that keep it on track.","head":[["link",{"rel":"canonical","href":"https://tuimark.vercel.app/guide/agents"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Tuimark"}],["meta",{"property":"og:title","content":"Working with coding agents | Tuimark"}],["meta",{"property":"og:description","content":"How a coding agent builds terminal UIs with Tuimark - the AGENTS.md briefing from tuimark agents, the validate, dump and play loop, and the rules that keep it on track."}],["meta",{"property":"og:url","content":"https://tuimark.vercel.app/guide/agents"}],["meta",{"name":"twitter:title","content":"Working with coding agents | Tuimark"}],["meta",{"name":"twitter:description","content":"How a coding agent builds terminal UIs with Tuimark - the AGENTS.md briefing from tuimark agents, the validate, dump and play loop, and the rules that keep it on track."}]]},"headers":[],"relativePath":"guide/agents.md","filePath":"guide/agents.md","lastUpdated":1792376055000}'),n={name:"guide/agents.md"};function o(d,e,r,h,l,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="working-with-coding-agents" tabindex="-1">Working with coding agents <a class="header-anchor" href="#working-with-coding-agents" aria-label="Permalink to &quot;Working with coding agents&quot;">​</a></h1><p>Tuimark was designed for a coding agent to write. An agent is good at editing text and reading structured output, and cannot look at a terminal. So in Tuimark the UI is text, and every frame can be printed as JSON: the agent edits files, renders them, reads back exactly what is on the screen, and repeats.</p><h2 id="the-briefing-agents-md" tabindex="-1">The briefing: AGENTS.md <a class="header-anchor" href="#the-briefing-agents-md" aria-label="Permalink to &quot;The briefing: AGENTS.md&quot;">​</a></h2><p><code>tuimark agents</code> prints a complete briefing for an agent: what to edit and what not to, the loop to follow, the tags and the attributes each takes, every CSS property and its values, the key tokens, every diagnostic code, and the behavior worth knowing. It is generated from the runtime&#39;s own catalogs, so it always matches the binary that printed it.</p><p>Put it where your agent looks for instructions:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tuimark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agents</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> AGENTS.md</span></span></code></pre></div><p>Regenerate it when you upgrade Tuimark. The <a href="/reference/">reference</a> pages on this site are generated from the same output.</p><p>For a project of your own, <code>tuimark agents --project</code> prints the same briefing without the pointers into the Tuimark repository, and <a href="/guide/tools#new"><code>tuimark new</code></a> writes it as the project&#39;s <code>AGENTS.md</code>. Agents and editors that need the vocabulary as data, not prose, read <a href="/guide/tools#catalog"><code>tuimark catalog</code></a>.</p><h2 id="the-loop" tabindex="-1">The loop <a class="header-anchor" href="#the-loop" aria-label="Permalink to &quot;The loop&quot;">​</a></h2><p>The whole method fits in four commands:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tuimark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.tui</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sample.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tuimark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dump</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.tui</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sample.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cols</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 80</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --rows</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tuimark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dump</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.tui</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sample.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cols</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 120</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rows</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tuimark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> play</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.tui</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sample.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;tab down enter&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --styles</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span></span></code></pre></div><ol><li><strong>Edit</strong> the <code>.tui</code>, the <code>.tcss</code>, and the sample data.</li><li><strong>Validate.</strong> Fix every error; read the warnings. Each diagnostic has a code, a position, and usually says what to write instead.</li><li><strong>Dump</strong> at 80 and 120 columns (and 40 if it has to fit a narrow pane). Read <code>grid</code> for what the screen shows and <code>nodes</code> for where each element landed, and check that <code>errors</code> is empty.</li><li><strong>Play</strong> the interactions: read <code>events</code> to confirm the right actions fired with the right <code>keys</code> and <code>value</code>, and <code>styles</code> to confirm that focus and selection actually change how cells look.</li></ol><p>Stop when the dumps match the intent at every width and nothing is reported. Then a person, or a host program, can run it for real.</p><p>An agent without a shell runs the same loop as MCP tool calls instead: <code>tuimark mcp</code> (0.3b) serves <code>validate</code>, <code>dump</code>, <code>play</code>, <code>inspect</code>, and the briefing itself as five tools over stdin/stdout, each returning exactly what the CLI command above prints. See <a href="/guide/mcp">MCP server</a> for how to register it.</p><h3 id="reading-a-dump" tabindex="-1">Reading a dump <a class="header-anchor" href="#reading-a-dump" aria-label="Permalink to &quot;Reading a dump&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Question</th><th>Where to look</th></tr></thead><tbody><tr><td>Does it render at all?</td><td><code>ok</code> is <code>true</code> and <code>errors</code> is empty</td></tr><tr><td>Is the text right?</td><td><code>grid</code>, one string per row</td></tr><tr><td>Is this panel the right size, in the right place?</td><td>the node&#39;s <code>x</code>, <code>y</code>, <code>w</code>, <code>h</code> in <code>nodes</code></td></tr><tr><td>Is the list scrolled to the selection?</td><td>the list&#39;s <code>scroll</code> and the <code>selected</code> item</td></tr><tr><td>Does focus start in the right place?</td><td><code>focus</code></td></tr><tr><td>Did a conditional class apply?</td><td>the node&#39;s <code>classes</code></td></tr><tr><td>Is the focused row highlighted?</td><td><code>play … --styles</code>: the row&#39;s spans have <code>&quot;a&quot;: [&quot;reverse&quot;]</code></td></tr><tr><td>Why is this cell this color?</td><td><code>tuimark inspect app.tui --at X,Y</code></td></tr></tbody></table><h2 id="rules-that-keep-an-agent-on-track" tabindex="-1">Rules that keep an agent on track <a class="header-anchor" href="#rules-that-keep-an-agent-on-track" aria-label="Permalink to &quot;Rules that keep an agent on track&quot;">​</a></h2><p>The briefing states them, and they are worth repeating in your own instructions:</p><ul><li><strong>Edit only view files</strong>: <code>*.tui</code>, <code>*.tcss</code>, and sample data. The view never needs Go.</li><li><strong>Never invent a tag or a property.</strong> The vocabulary is closed; an invented one is a diagnostic, not a feature. Check the <a href="/reference/tags">tags</a> and <a href="/reference/css">properties</a> instead.</li><li><strong>No logic in markup.</strong> If the view needs a computed value, it goes in the data, and the host computes it.</li><li><strong>No terminal UI framework code.</strong> No hand-written layout, widths, padding, or truncation in the host; Tuimark does all of that from the document.</li><li><strong>Name actions; do not implement them in markup.</strong> <code>on:select=&quot;open&quot;</code> is a name, and the host decides what it means.</li></ul><h2 id="a-prompt-that-works" tabindex="-1">A prompt that works <a class="header-anchor" href="#a-prompt-that-works" aria-label="Permalink to &quot;A prompt that works&quot;">​</a></h2><blockquote><p>Build the view for a deploy dashboard in <code>ui/app.tui</code> and <code>ui/theme.tcss</code>, with realistic data in <code>ui/sample.json</code>: a pipeline list on the left, a log panel on the right, a status bar, and a confirm modal for deploying. Use <code>&lt;tui version=&quot;3&quot;&gt;</code>. Read <code>AGENTS.md</code> first. Loop with <code>tuimark validate</code> and <code>tuimark dump --format json</code> at 80 and 120 columns until there are no diagnostics, and check the keymap with <code>tuimark play</code>. Do not write any Go. When you are done, list the action names the view fires.</p></blockquote><h2 id="handing-off-to-the-host" tabindex="-1">Handing off to the host <a class="header-anchor" href="#handing-off-to-the-host" aria-label="Permalink to &quot;Handing off to the host&quot;">​</a></h2><p>When the view is done, the host needs to know what to handle. <code>tuimark validate app.tui --json</code> includes the action catalog: every name, where it is used, and which are built in. Save the names the host implements to <code>actions.json</code>, and from then on:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tuimark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.tui</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --catalog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> actions.json</span></span></code></pre></div><p>reports any action the view fires that the host does not know (<code>B004</code>), which catches a renamed action on either side. In Go, <code>ui.Catalog()</code> gives the same list; a <a href="/guide/testing#go-tests">test</a> can require a handler for every name.</p><h2 id="keeping-it-honest" tabindex="-1">Keeping it honest <a class="header-anchor" href="#keeping-it-honest" aria-label="Permalink to &quot;Keeping it honest&quot;">​</a></h2><ul><li>Commit goldens for the sizes you checked (<a href="/guide/testing#golden-dumps">testing</a>): the next agent that edits the view gets a failing test and a diff, not a surprise.</li><li>Keep <code>sample.json</code> realistic, with the long names, empty lists, and wide characters real data will have.</li></ul>`,27)])])}const g=t(n,[["render",o]]);export{k as __pageData,g as default};
